COMMENT ON COLUMN webhook_endpoints.fallback_url IS '主要地址失败后的备用地址';
COMMENT ON COLUMN webhook_endpoints.secret_blob IS 'AES-GCM 加密的 HMAC 签名密钥';
COMMENT ON COLUMN webhook_endpoints.key_version IS '加密主密钥版本';
COMMENT ON COLUMN webhook_endpoints.status IS '端点状态，由应用校验 active、paused 或 disabled';
COMMENT ON COLUMN webhook_endpoints.failure_count IS '连续失败次数';
COMMENT ON COLUMN webhook_endpoints.paused_at IS '自动或手动暂停时间';
COMMENT ON COLUMN webhook_endpoints.version IS '乐观锁版本号';
COMMENT ON COLUMN webhook_endpoints.created_at IS '创建时间';
COMMENT ON COLUMN webhook_endpoints.updated_at IS '最后更新时间';
COMMENT ON COLUMN webhook_endpoints.deleted_at IS '软删除时间';

CREATE INDEX webhook_endpoints_workspace_status_idx ON webhook_endpoints (workspace_id, status) WHERE deleted_at IS NULL;

CREATE TABLE webhook_endpoint_events (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    webhook_endpoint_id uuid NOT NULL,
    event_pattern varchar(160) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE webhook_endpoint_events IS '出站 Webhook 端点订阅的事件模式';
COMMENT ON COLUMN webhook_endpoint_events.id IS '订阅关系 UUID';
COMMENT ON COLUMN webhook_endpoint_events.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN webhook_endpoint_events.webhook_endpoint_id IS 'Webhook 端点 UUID';
COMMENT ON COLUMN webhook_endpoint_events.event_pattern IS '事件模式，例如 auth.*、connection.* 或 sync.completed';
COMMENT ON COLUMN webhook_endpoint_events.created_at IS '创建时间';

CREATE UNIQUE INDEX webhook_endpoint_events_uq ON webhook_endpoint_events (workspace_id, webhook_endpoint_id, event_pattern);

CREATE TABLE webhook_sources (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    source_key varchar(100) NOT NULL,
    name varchar(160) NOT NULL,
