    secret_blob bytea,
    key_version smallint NOT NULL DEFAULT 1,
    subscribed_events varchar(160)[] NOT NULL DEFAULT '{}'::varchar[],
    settings jsonb NOT NULL DEFAULT '{}'::jsonb,
    version bigint NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz
);

COMMENT ON TABLE webhook_sources IS '外部系统入站 Webhook 入口及签名验证配置';
COMMENT ON COLUMN webhook_sources.id IS '入站源 UUID';
COMMENT ON COLUMN webhook_sources.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN webhook_sources.source_key IS '公开路径使用的不可猜测稳定标识';
COMMENT ON COLUMN webhook_sources.name IS '入站源显示名称';
COMMENT ON COLUMN webhook_sources.integration_id IS '所属集成 UUID';
COMMENT ON COLUMN webhook_sources.status IS '入站源状态，由应用校验 active 或 disabled';
COMMENT ON COLUMN webhook_sources.signature_type IS '提供商签名验证类型';
COMMENT ON COLUMN webhook_sources.secret_blob IS 'AES-GCM 加密后的 Webhook 验签秘密';
COMMENT ON COLUMN webhook_sources.key_version IS '加密主密钥版本';
COMMENT ON COLUMN webhook_sources.subscribed_events IS '允许接收的提供商事件类型';
COMMENT ON COLUMN webhook_sources.settings IS '提供商验签和事件映射的非敏感设置';
COMMENT ON COLUMN webhook_sources.version IS '乐观锁版本号';
COMMENT ON COLUMN webhook_sources.created_at IS '创建时间';
COMMENT ON COLUMN webhook_sources.updated_at IS '最后更新时间';
COMMENT ON COLUMN webhook_sources.deleted_at IS '软删除时间';

CREATE UNIQUE INDEX webhook_sources_workspace_key_uq ON webhook_sources (workspace_id, source_key) WHERE deleted_at IS NULL;
CREATE INDEX webhook_sources_integration_idx ON webhook_sources (workspace_id, integration_id, status) WHERE deleted_at IS NULL;

CREATE TABLE webhook_ingress_events (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    webhook_source_id uuid NOT NULL,
