    event_type varchar(160) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(24) NOT NULL,
    operation_id uuid,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    expires_at timestamptz NOT NULL
);

COMMENT ON TABLE webhook_ingress_events IS '入站 Webhook 验签后的去重记录和受限事件内容';
COMMENT ON COLUMN webhook_ingress_events.id IS '入站事件 UUID';
COMMENT ON COLUMN webhook_ingress_events.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN webhook_ingress_events.webhook_source_id IS '入站源 UUID';
COMMENT ON COLUMN webhook_ingress_events.provider_event_id IS '提供商事件 ID 或请求体哈希';
COMMENT ON COLUMN webhook_ingress_events.event_type IS '规范化事件类型';
COMMENT ON COLUMN webhook_ingress_events.payload IS '经过大小限制和敏感字段处理的事件 JSON';
COMMENT ON COLUMN webhook_ingress_events.status IS '处理状态，由应用校验 received、processed、ignored 或 failed';
COMMENT ON COLUMN webhook_ingress_events.operation_id IS '关联的统一运行记录 UUID';
COMMENT ON COLUMN webhook_ingress_events.received_at IS '接收时间';
COMMENT ON COLUMN webhook_ingress_events.processed_at IS '处理完成时间';
COMMENT ON COLUMN webhook_ingress_events.expires_at IS '去重和内容保留到期时间';

