CREATE INDEX webhook_ingress_events_received_idx ON webhook_ingress_events (workspace_id, received_at DESC, id DESC);

CREATE TABLE outbox_events (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    event_type varchar(160) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    dedupe_key varchar(255) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(24) NOT NULL DEFAULT 'pending',
    available_at timestamptz NOT NULL DEFAULT now(),
    attempt integer NOT NULL DEFAULT 0,
    lease_owner varchar(160),
    lease_expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz
);

COMMENT ON TABLE outbox_events IS '与业务写入同事务提交的可靠平台事件';
COMMENT ON COLUMN outbox_events.id IS '事件 UUID，同时作为对外 event id';
COMMENT ON COLUMN outbox_events.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN outbox_events.event_type IS '规范化事件类型';
COMMENT ON COLUMN outbox_events.aggregate_type IS '产生事件的资源类型';
COMMENT ON COLUMN outbox_events.aggregate_id IS '产生事件的资源 UUID';
