COMMENT ON COLUMN outbox_events.available_at IS '允许 dispatcher 处理的时间';
COMMENT ON COLUMN outbox_events.attempt IS '发布尝试次数';
COMMENT ON COLUMN outbox_events.lease_owner IS '当前 dispatcher 实例标识';
COMMENT ON COLUMN outbox_events.lease_expires_at IS '发布租约过期时间';
COMMENT ON COLUMN outbox_events.created_at IS '创建时间';
COMMENT ON COLUMN outbox_events.published_at IS '完成端点展开的时间';

CREATE UNIQUE INDEX outbox_events_workspace_dedupe_uq ON outbox_events (workspace_id, dedupe_key);
CREATE INDEX outbox_events_claim_idx ON outbox_events (available_at, id) WHERE status = 'pending';

CREATE TABLE webhook_deliveries (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    outbox_event_id uuid NOT NULL,
    webhook_endpoint_id uuid NOT NULL,
    target_url varchar(2048) NOT NULL,
    status varchar(24) NOT NULL,
    attempt_count integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz,
    last_http_status integer,
    last_error varchar(2000),
    created_at timestamptz NOT NULL DEFAULT now(),
    delivered_at timestamptz,
    dead_at timestamptz
);

COMMENT ON TABLE webhook_deliveries IS '一个 outbox 事件到一个出站端点的投递状态';
COMMENT ON COLUMN webhook_deliveries.id IS '投递 UUID';
COMMENT ON COLUMN webhook_deliveries.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN webhook_deliveries.outbox_event_id IS '平台 outbox 事件 UUID';
COMMENT ON COLUMN webhook_deliveries.webhook_endpoint_id IS '目标 Webhook 端点 UUID';
COMMENT ON COLUMN webhook_deliveries.target_url IS '本次投递使用的主地址或备用地址快照';
COMMENT ON COLUMN webhook_deliveries.status IS '投递状态，由应用校验 pending、retrying、delivered 或 dead';
COMMENT ON COLUMN webhook_deliveries.attempt_count IS '已经完成的 HTTP 尝试次数';
COMMENT ON COLUMN webhook_deliveries.next_attempt_at IS '下一次重试时间';
COMMENT ON COLUMN webhook_deliveries.last_http_status IS '最近一次目标 HTTP 状态码';
COMMENT ON COLUMN webhook_deliveries.last_error IS '最近一次投递错误摘要';
COMMENT ON COLUMN webhook_deliveries.created_at IS '创建时间';
COMMENT ON COLUMN webhook_deliveries.delivered_at IS '成功投递时间';
COMMENT ON COLUMN webhook_deliveries.dead_at IS '超过重试上限进入 dead 状态的时间';

CREATE UNIQUE INDEX webhook_deliveries_event_endpoint_uq ON webhook_deliveries (workspace_id, outbox_event_id, webhook_endpoint_id);
CREATE INDEX webhook_deliveries_retry_idx ON webhook_deliveries (next_attempt_at, id) WHERE status IN ('pending', 'retrying');
CREATE INDEX webhook_deliveries_workspace_created_idx ON webhook_deliveries (workspace_id, created_at DESC, id DESC);

CREATE TABLE webhook_delivery_attempts (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    webhook_delivery_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    target_url varchar(2048) NOT NULL,
    request_id varchar(100) NOT NULL,
    http_status integer,
    duration_ms integer,
    response_body varchar(8192),
    error_message varchar(2000),
    created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE webhook_delivery_attempts IS 'Webhook 投递每次 HTTP 尝试的受限明细';
COMMENT ON COLUMN webhook_delivery_attempts.id IS '投递尝试 UUID';
COMMENT ON COLUMN webhook_delivery_attempts.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN webhook_delivery_attempts.webhook_delivery_id IS 'Webhook 投递 UUID';
COMMENT ON COLUMN webhook_delivery_attempts.attempt_no IS '从 1 开始的尝试序号';
COMMENT ON COLUMN webhook_delivery_attempts.target_url IS '本次尝试的目标地址';
COMMENT ON COLUMN webhook_delivery_attempts.request_id IS '关联日志的请求 ID';
COMMENT ON COLUMN webhook_delivery_attempts.http_status IS '目标返回的 HTTP 状态码';
COMMENT ON COLUMN webhook_delivery_attempts.duration_ms IS '本次 HTTP 请求耗时毫秒数';
COMMENT ON COLUMN webhook_delivery_attempts.response_body IS '截断并脱敏后的响应体';
COMMENT ON COLUMN webhook_delivery_attempts.error_message IS '网络或协议错误摘要';
COMMENT ON COLUMN webhook_delivery_attempts.created_at IS '尝试时间';

CREATE UNIQUE INDEX webhook_delivery_attempts_delivery_no_uq ON webhook_delivery_attempts (webhook_delivery_id, attempt_no);
CREATE INDEX webhook_delivery_attempts_workspace_created_idx ON webhook_delivery_attempts (workspace_id, created_at DESC);

CREATE TABLE operation_runs (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    request_id varchar(100) NOT NULL,
    kind varchar(24) NOT NULL,
    name varchar(180) NOT NULL,
    status varchar(24) NOT NULL,
    system_id uuid,
    integration_id uuid,
    connection_id uuid,
    action_id uuid,
    sync_task_id uuid,
    runtime_token_id uuid,
    source varchar(32) NOT NULL,
    http_status integer,
    input jsonb,
    output jsonb,
    error_code varchar(120),
    error_message varchar(2000),
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    expires_at timestamptz NOT NULL
);

COMMENT ON TABLE operation_runs IS 'Action、Sync、Webhook 和 Auth 的统一运行记录';
COMMENT ON COLUMN operation_runs.id IS '运行 UUID';
COMMENT ON COLUMN operation_runs.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN operation_runs.request_id IS '贯穿 HTTP、worker 和日志的请求 ID';
COMMENT ON COLUMN operation_runs.kind IS '运行类型，由应用校验 action、sync、webhook 或 auth';
COMMENT ON COLUMN operation_runs.name IS '页面显示的操作或任务名称快照';
COMMENT ON COLUMN operation_runs.status IS '运行状态，由应用校验 queued、running、success、failed 或 cancelled';
COMMENT ON COLUMN operation_runs.system_id IS '关联系统 UUID';
COMMENT ON COLUMN operation_runs.integration_id IS '关联集成 UUID';
COMMENT ON COLUMN operation_runs.connection_id IS '关联连接账号 UUID';
COMMENT ON COLUMN operation_runs.action_id IS '关联操作 UUID';
COMMENT ON COLUMN operation_runs.sync_task_id IS '关联同步任务 UUID';
COMMENT ON COLUMN operation_runs.runtime_token_id IS '发起运行的机器令牌 UUID';
COMMENT ON COLUMN operation_runs.source IS '触发来源，例如 api、manual、schedule 或 webhook';
COMMENT ON COLUMN operation_runs.http_status IS '外部系统或最终响应状态码';
COMMENT ON COLUMN operation_runs.input IS '脱敏且受大小限制的输入 JSON';
COMMENT ON COLUMN operation_runs.output IS '脱敏且受大小限制的输出 JSON';
COMMENT ON COLUMN operation_runs.error_code IS '稳定错误代码';
COMMENT ON COLUMN operation_runs.error_message IS '脱敏错误摘要';
COMMENT ON COLUMN operation_runs.started_at IS '开始时间';
COMMENT ON COLUMN operation_runs.completed_at IS '完成时间';
COMMENT ON COLUMN operation_runs.expires_at IS '按平台保留策略计算的清理时间';

CREATE UNIQUE INDEX operation_runs_workspace_request_uq ON operation_runs (workspace_id, request_id);
CREATE INDEX operation_runs_workspace_started_idx ON operation_runs (workspace_id, started_at DESC, id DESC);
CREATE INDEX operation_runs_filter_idx ON operation_runs (workspace_id, kind, status, started_at DESC);
CREATE INDEX operation_runs_connection_idx ON operation_runs (workspace_id, connection_id, started_at DESC) WHERE connection_id IS NOT NULL;

CREATE TABLE operation_events (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    sequence integer NOT NULL,
    level varchar(16) NOT NULL,
    message varchar(1000) NOT NULL,
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE operation_events IS '运行详情时间线中的结构化事件';
COMMENT ON COLUMN operation_events.id IS '运行事件 UUID';
COMMENT ON COLUMN operation_events.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN operation_events.operation_id IS '统一运行记录 UUID';
COMMENT ON COLUMN operation_events.sequence IS '运行内部严格递增的事件序号';
COMMENT ON COLUMN operation_events.level IS '日志级别，由应用校验 debug、info、warn 或 error';
COMMENT ON COLUMN operation_events.message IS '脱敏后的简短事件消息';
COMMENT ON COLUMN operation_events.attributes IS '不包含秘密的结构化上下文';
COMMENT ON COLUMN operation_events.created_at IS '事件时间';

CREATE UNIQUE INDEX operation_events_operation_sequence_uq ON operation_events (operation_id, sequence);
CREATE INDEX operation_events_workspace_created_idx ON operation_events (workspace_id, created_at DESC);

CREATE TABLE idempotency_records (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    runtime_token_id uuid NOT NULL,
    scope varchar(180) NOT NULL,
    idempotency_key varchar(255) NOT NULL,
    request_fingerprint char(64) NOT NULL,
    status varchar(24) NOT NULL,
    http_status integer,
    response jsonb,
    operation_id uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL
);

COMMENT ON TABLE idempotency_records IS '运行 API 的幂等占位与结果重放';
COMMENT ON COLUMN idempotency_records.id IS '幂等记录 UUID';
COMMENT ON COLUMN idempotency_records.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN idempotency_records.runtime_token_id IS '发起请求的运行时令牌 UUID';
COMMENT ON COLUMN idempotency_records.scope IS '操作标识或其他幂等作用域';
COMMENT ON COLUMN idempotency_records.idempotency_key IS '客户端提供的幂等键';
COMMENT ON COLUMN idempotency_records.request_fingerprint IS '规范化请求内容 SHA-256';
COMMENT ON COLUMN idempotency_records.status IS '状态，由应用校验 claimed 或 completed';
COMMENT ON COLUMN idempotency_records.http_status IS '可重放的 HTTP 状态码';
COMMENT ON COLUMN idempotency_records.response IS '脱敏且受大小限制的响应 envelope';
COMMENT ON COLUMN idempotency_records.operation_id IS '首次执行产生的运行 UUID';
COMMENT ON COLUMN idempotency_records.created_at IS '占位创建时间';
COMMENT ON COLUMN idempotency_records.expires_at IS '幂等记录过期时间';

CREATE UNIQUE INDEX idempotency_records_scope_key_uq ON idempotency_records (workspace_id, runtime_token_id, scope, idempotency_key);
CREATE INDEX idempotency_records_expiry_idx ON idempotency_records (expires_at);

CREATE TABLE audit_logs (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    request_id varchar(100) NOT NULL,
    actor_type varchar(24) NOT NULL,
    actor_id uuid,
    actor_label varchar(320) NOT NULL,
    action varchar(180) NOT NULL,
    resource_type varchar(80) NOT NULL,
    resource_id uuid,
    resource_label varchar(320),
    ip_address inet,
    before_data jsonb,
    after_data jsonb,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz
);

COMMENT ON TABLE audit_logs IS '控制面敏感变更审计日志';
COMMENT ON COLUMN audit_logs.id IS '审计事件 UUID';
COMMENT ON COLUMN audit_logs.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN audit_logs.request_id IS '关联 HTTP 请求 ID';
COMMENT ON COLUMN audit_logs.actor_type IS '操作者类型，由应用校验 user、admin_token、runtime_token 或 system';
COMMENT ON COLUMN audit_logs.actor_id IS '操作者资源 UUID';
COMMENT ON COLUMN audit_logs.actor_label IS '操作者名称或邮箱快照';
COMMENT ON COLUMN audit_logs.action IS '稳定审计动作，例如 member.role_updated';
COMMENT ON COLUMN audit_logs.resource_type IS '目标资源类型';
COMMENT ON COLUMN audit_logs.resource_id IS '目标资源 UUID';
COMMENT ON COLUMN audit_logs.resource_label IS '目标资源显示名称快照';
COMMENT ON COLUMN audit_logs.ip_address IS '客户端 IP';
COMMENT ON COLUMN audit_logs.before_data IS '变更前的脱敏字段';
COMMENT ON COLUMN audit_logs.after_data IS '变更后的脱敏字段';
COMMENT ON COLUMN audit_logs.metadata IS '请求来源等非敏感上下文';
COMMENT ON COLUMN audit_logs.created_at IS '审计事件时间';
COMMENT ON COLUMN audit_logs.expires_at IS '可选清理时间；永久保留时为空';

CREATE INDEX audit_logs_workspace_created_idx ON audit_logs (workspace_id, created_at DESC, id DESC);
CREATE INDEX audit_logs_resource_idx ON audit_logs (workspace_id, resource_type, resource_id, created_at DESC);
CREATE INDEX audit_logs_action_idx ON audit_logs (workspace_id, action, created_at DESC);

CREATE TABLE platform_settings (
    workspace_id uuid PRIMARY KEY,
    platform_name varchar(160) NOT NULL,
    public_base_url varchar(2048) NOT NULL,
    runtime_parameters jsonb NOT NULL DEFAULT '{}'::jsonb,
    operation_retention_days integer NOT NULL DEFAULT 30,
    audit_retention_days integer,
    version bigint NOT NULL DEFAULT 1,
    updated_by uuid NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE platform_settings IS '平台常规设置、允许编辑的运行参数和数据保留策略';
COMMENT ON COLUMN platform_settings.workspace_id IS '所属工作区 UUID，同时作为主键';
COMMENT ON COLUMN platform_settings.platform_name IS '页面和通知使用的平台名称';
COMMENT ON COLUMN platform_settings.public_base_url IS 'OAuth 回调和公开链接使用的基础地址';
COMMENT ON COLUMN platform_settings.runtime_parameters IS '经过服务端白名单校验的运行参数，不允许任意进程环境变量';
COMMENT ON COLUMN platform_settings.operation_retention_days IS '运行日志保留天数';
COMMENT ON COLUMN platform_settings.audit_retention_days IS '审计日志保留天数；为空表示永久';
COMMENT ON COLUMN platform_settings.version IS '乐观锁版本号';
COMMENT ON COLUMN platform_settings.updated_by IS '最近修改用户 UUID';
COMMENT ON COLUMN platform_settings.updated_at IS '最后更新时间';

CREATE TABLE platform_secrets (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    secret_key varchar(100) NOT NULL,
    display_prefix varchar(32),
    secret_hash char(64),
    secret_blob bytea,
    key_version smallint NOT NULL DEFAULT 1,
    status varchar(24) NOT NULL,
    grace_expires_at timestamptz,
    last_used_at timestamptz,
    rotated_from_id uuid,
    created_by uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz
);

COMMENT ON TABLE platform_secrets IS '服务端密钥、公开标识和 Webhook 密钥的版本化保存';
COMMENT ON COLUMN platform_secrets.id IS '平台密钥 UUID';
COMMENT ON COLUMN platform_secrets.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN platform_secrets.secret_key IS '密钥用途，例如 server_key、public_key 或 webhook_signing_key';
COMMENT ON COLUMN platform_secrets.display_prefix IS '页面展示的非敏感密钥前缀';
COMMENT ON COLUMN platform_secrets.secret_hash IS '只需要校验而无需取回的密钥哈希';
COMMENT ON COLUMN platform_secrets.secret_blob IS '需要运行时取回的 AES-GCM 密文';
COMMENT ON COLUMN platform_secrets.key_version IS '加密主密钥版本';
COMMENT ON COLUMN platform_secrets.status IS '密钥状态，由应用校验 active、grace 或 revoked';
COMMENT ON COLUMN platform_secrets.grace_expires_at IS '轮换宽限期截止时间';
COMMENT ON COLUMN platform_secrets.last_used_at IS '最近使用时间';
COMMENT ON COLUMN platform_secrets.rotated_from_id IS '本版本替代的旧密钥 UUID';
COMMENT ON COLUMN platform_secrets.created_by IS '创建或轮换密钥的用户 UUID';
COMMENT ON COLUMN platform_secrets.created_at IS '创建时间';
COMMENT ON COLUMN platform_secrets.revoked_at IS '撤销时间';

CREATE INDEX platform_secrets_active_idx ON platform_secrets (workspace_id, secret_key, created_at DESC) WHERE revoked_at IS NULL;

CREATE TABLE metric_hourly (
    id uuid PRIMARY KEY,
    workspace_id uuid NOT NULL,
    bucket_start timestamptz NOT NULL,
    kind varchar(24) NOT NULL,
    system_id uuid,
    action_id uuid,
    status varchar(24) NOT NULL,
    request_count bigint NOT NULL DEFAULT 0,
    success_count bigint NOT NULL DEFAULT 0,
    failure_count bigint NOT NULL DEFAULT 0,
    duration_sum_ms bigint NOT NULL DEFAULT 0,
    duration_max_ms integer NOT NULL DEFAULT 0,
    records_count bigint NOT NULL DEFAULT 0,
    updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE metric_hourly IS '运行中心图表使用的小时级聚合事实';
COMMENT ON COLUMN metric_hourly.id IS '聚合行 UUID';
COMMENT ON COLUMN metric_hourly.workspace_id IS '所属工作区 UUID';
COMMENT ON COLUMN metric_hourly.bucket_start IS 'UTC 小时桶开始时间';
COMMENT ON COLUMN metric_hourly.kind IS '运行类型 action、sync、webhook 或 auth';
COMMENT ON COLUMN metric_hourly.system_id IS '可选系统维度 UUID';
COMMENT ON COLUMN metric_hourly.action_id IS '可选操作维度 UUID';
COMMENT ON COLUMN metric_hourly.status IS '聚合状态维度';
COMMENT ON COLUMN metric_hourly.request_count IS '总运行次数';
COMMENT ON COLUMN metric_hourly.success_count IS '成功次数';
COMMENT ON COLUMN metric_hourly.failure_count IS '失败次数';
COMMENT ON COLUMN metric_hourly.duration_sum_ms IS '总耗时毫秒数，用于计算平均耗时';
COMMENT ON COLUMN metric_hourly.duration_max_ms IS '最大耗时毫秒数';
COMMENT ON COLUMN metric_hourly.records_count IS '同步读取或写入的记录数量';
COMMENT ON COLUMN metric_hourly.updated_at IS '最近聚合更新时间';

CREATE UNIQUE INDEX metric_hourly_dimensions_uq ON metric_hourly (
    workspace_id,
    bucket_start,
    kind,
    (coalesce(system_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(action_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    status
);
CREATE INDEX metric_hourly_workspace_bucket_idx ON metric_hourly (workspace_id, bucket_start DESC);

